import pandas as pd

def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()

    # watermark map: device_id -> applied_event_ts
    watermark = dict(zip(target["device_id"], target["applied_event_ts"]))
    current_reading = dict(zip(target["device_id"], target["reading"]))

    # For devices with watermark, filter cdc events strictly greater than watermark
    # For devices without watermark (new devices), all events are eligible

    def eligible(row):
        dev = row["device_id"]
        if dev in watermark:
            wm = watermark[dev]
            return row["event_ts"] > wm
        else:
            return True

    if len(cdc) > 0:
        mask = cdc.apply(eligible, axis=1)
        surviving = cdc[mask].copy()
    else:
        surviving = cdc.copy()

    result_rows = {}

    # start with carry-forward of all target devices
    for _, row in target.iterrows():
        result_rows[row["device_id"]] = {
            "device_id": row["device_id"],
            "reading": row["reading"],
            "applied_event_ts": row["applied_event_ts"],
        }

    if len(surviving) > 0:
        # pick winner per device: max by (event_ts, event_seq)
        surviving_sorted = surviving.sort_values(
            by=["event_ts", "event_seq"], ascending=[True, True]
        )
        winners = surviving_sorted.groupby("device_id", as_index=False).tail(1)

        for _, row in winners.iterrows():
            dev = row["device_id"]
            result_rows[dev] = {
                "device_id": dev,
                "reading": row["reading"],
                "applied_event_ts": row["event_ts"],
            }

    if result_rows:
        out = pd.DataFrame(list(result_rows.values()))
        out = out[["device_id", "reading", "applied_event_ts"]]
        out["device_id"] = out["device_id"].astype("int64")
        out["reading"] = out["reading"].astype("float64")
        out["applied_event_ts"] = pd.to_datetime(out["applied_event_ts"])
    else:
        out = pd.DataFrame(columns=["device_id", "reading", "applied_event_ts"])
        out["device_id"] = out["device_id"].astype("int64")
        out["reading"] = out["reading"].astype("float64")
        out["applied_event_ts"] = pd.to_datetime(out["applied_event_ts"])

    return {"new_snapshot": out}
